import type { Metadata } from "next";
import Breadcrumb from "@/components/header/breadcrumb";

export const dynamic = "force-static";
export const metadata: Metadata = {
  title: "Legal Disclaimer - TravelShop Booking",
  description:
    "Read TravelShop Booking Legal Disclaimer for important information and disclosures. Trust in our transparency and expertise.",
  alternates: {
    canonical: "https://travelshopbooking.com/legal-disclaimer",
  },
};

const sections = [
  {
    image: "/images/legal1.webp",
    imageLeft: true,
    paragraphs: [
      'TravelShop Booking is a dedicated and comprehensive tour operator that also integrates a wide range of travel agency products and services sourced from various destinations across the world. Our platform serves as a bridge connecting travelers with diverse tour options, accommodations, and experiences provided by third-party agencies and service providers. However, it is important to note that the information presented on our website and platform is displayed strictly on an "as is" basis, without any form of warranty, guarantee, or assurance regarding its accuracy, reliability, or completeness when it pertains to third-party content. While we are committed to facilitating a seamless and enriching travel experience, we cannot and do not assume any responsibility for potential discrepancies, misrepresentations, or inaccuracies in the details, descriptions, or promotional materials provided by external sources.',
      "Additionally, TravelShop Booking does not hold any liability concerning the accuracy, authenticity, or legitimacy of various types of content, including but not limited to textual descriptions, images, videos, licensing information, pricing details, or any other materials that may be displayed within our platform. The responsibility for the completeness, legality, and reliability of such information rests entirely with the respective third-party providers, and we make no claims regarding the validity or credibility of the data they present. As a result, any risks associated with reliance on third-party content are assumed solely by the user.",
    ],
  },
  {
    image: "/images/legal2.webp",
    imageLeft: false,
    paragraphs: [
      "It is important to understand that our liability as TravelShop Booking is strictly limited to the self-promoted products, services, and offerings that are directly managed and overseen by our team. For these specific services, we ensure adherence to high-quality standards, accuracy in descriptions, and a commitment to delivering an exceptional customer experience. However, for all other products, services, or information provided by independent third-party entities, we encourage users to conduct their own research, verify details, and make informed decisions before proceeding with any bookings or transactions.",
      "Should you have any concerns, complaints, or disputes regarding the legitimacy, authenticity, or copyright status of any published content, we strongly advise you to directly contact the respective service provider, agency, or content owner as listed. TravelShop Booking does not intervene in disputes related to copyright issues, licensing concerns, or potential misinformation published by external parties. If you come across any inaccuracies or believe that certain materials violate copyright laws, we recommend reaching out to the original source or rightful owner to address the matter in accordance with applicable regulations.",
    ],
  },
  {
    image: "/images/legal3.webp",
    imageLeft: true,
    paragraphs: [
      "At TravelShop Booking, our priority is to create a trustworthy and user-friendly platform that enhances travel experiences while offering access to a diverse selection of tours, travel packages, and related services. We aim to connect travelers with reputable providers, ensuring a seamless and enjoyable booking experience. However, while we strive to maintain a high standard of service, it is essential for users to remain diligent when making travel arrangements. We strongly recommend that travelers carefully review all details, including pricing, terms, and conditions, before proceeding with any bookings. Exercising discretion and conducting independent verification can help ensure that the selected services align with personal expectations and requirements.",
      "If you require further clarification regarding our policies, responsibilities, or the nature of the content presented on our platform, we encourage you to reach out to our customer support team for additional assistance. Our team is available to address inquiries, provide guidance, and help users navigate any uncertainties they may have. We are committed to delivering a positive user experience, and we value open communication with our customers. Whether you need assistance understanding a policy, verifying specific details, or resolving any concerns related to our platform, we are here to help.",
    ],
  },
];

export default function LegalDisclaimerPage() {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Header band */}
      <section className="tw-bg-[#faf9fc] tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[1100px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-10 md:tw-py-14">
          <Breadcrumb
            items={[
              { pageTitle: "Legal Disclaimer", pageUrl: "/legal-disclaimer" },
            ]}
          />
          <h1 className="tw-mt-4 tw-text-[clamp(28px,4vw,44px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Legal Disclaimer
          </h1>
          <p className="tw-mt-4 tw-mb-0 tw-text-[16px] tw-leading-[1.7] tw-font-semibold tw-text-[#5d556c] tw-max-w-[760px]">
            TravelShop Booking is a Tour operator and a includes Travel Agencies
            products from all around the world hence the information displayed
            &ldquo;as is&rdquo; without warranty or assurance of any kind for the
            3rd parties.
          </p>
        </div>
      </section>

      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1100px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-space-y-10 lg:tw-space-y-14">
          {sections.map((section, i) => (
            <div
              key={i}
              className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-[360px_1fr] tw-gap-8 lg:tw-gap-12 tw-items-center"
            >
              <div className={section.imageLeft ? "" : "lg:tw-order-2"}>
                <img
                  src={section.image}
                  alt="Legal disclaimer"
                  loading="lazy"
                  className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
                />
              </div>
              <div
                className={`tw-space-y-4 tw-text-[15px] tw-leading-[1.8] tw-text-[#5d556c] ${
                  section.imageLeft ? "" : "lg:tw-order-1"
                }`}
              >
                {section.paragraphs.map((p, j) => (
                  <p key={j} className="tw-m-0">
                    {p}
                  </p>
                ))}
              </div>
            </div>
          ))}
        </div>
      </section>
    </main>
  );
}
